import{z as d,x as E,o as l,c as A,q as s,j as n,D as e,d as r,s as i,S as p,b as o}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"HyperLogLog","description":"","frontmatter":{"title":"HyperLogLog","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hyperloglog.md","filePath":"cs/hyperloglog.md","lastUpdated":1791413859000}'),m={name:"cs/hyperloglog.md"};function h(g,a,B,c,u,L){const t=E("Mermaid");return l(),A("div",null,[a[2]||(a[2]=s('<h1 id="hyperloglog" tabindex="-1">HyperLogLog <a class="header-anchor" href="#hyperloglog" aria-label="Permalink to &quot;HyperLogLog&quot;">​</a></h1><div class="epigraph"><p>看哈希前导零的最大游程：越长越暗示基数大；多桶平均压方差，空间几千字节估上亿不同键。</p><footer>—— 据 Flajolet, Fusy, Gandouet and Meunier, HyperLogLog: The Analysis of a Near-Optimal Cardinality Estimation Algorithm, AOFA 2007；Durand and Flajolet, LogLog, 2003 整理</footer></div><p><a href="/cs/count-min-sketch">上一课</a> 估单个键的频次，不直接给「有多少不同键」。精确去重要 \\(\\Theta(n)\\) 内存。<a href="/cs/universal-hashing">通用散列</a> 把键搅匀。本课不取 min 计数。缺口是 HyperLogLog：桶内记 \\(\\rho(h(x))\\)（前导零+1）的最大，再用调和平均。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基数 \\(n=|\\mathrm{set}|\\)。随机哈希下 \\(\\max\\rho\\) 约 \\(\\log_2 n\\)。单桶方差大：拆成 \\(m=2^p\\) 桶，用 \\(h\\) 的前 \\(p\\) 比特选桶，其余算 \\(\\rho\\)。估计 \\(\\alpha_m m^2 \\big/\\sum 2^{-M_j}\\)。缺口是<strong>用极值统计代替存集合</strong>，标准误差约 \\(1.04/\\sqrt{m}\\)。</p><p><span class="marginnote">数字实例：\\(m=2^{14}=16384\\) 桶时，标准误差约 \\(1.04/128\\approx 0.8\\%\\)——估一亿个键大约偏差八十万，但寄存器只占 \\(16384\\times 6\\) 比特 ≈ 12 KB。精确存一亿个 8 字节键要约 800 MB：近五个数量级的空间换不到 1% 的误差。</span></p><p><span class="marginnote">Flajolet et al., AOFA 2007。前身 Flajolet–Martin、Durand–Flajolet LogLog。实践 HyperLogLog++ 修小基数偏差，本课点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>add(x)</code>：算哈希，更新对应桶 max。<code>merge</code>：对桶逐个 \\(\\max\\)，适合分布式。小 \\(n\\) 时用线性计数修正（空桶）。不要用 HLL 估频次——那是 CM。</p><p><span class="marginnote">常见误区：以为桶里记的是「最大的哈希值」。实际记的是前导零个数加一：哈希以二进制 \\(0001\\ldots\\) 开头则 \\(\\rho=4\\)，以 \\(011\\ldots\\) 开头则 \\(\\rho=2\\)。前导零越多，说明「这么稀罕的开头都撞上了」，暗示见过的不同键很多。</span></p><p><span class="marginnote">直觉类比：把键掷进 16384 个桶，每桶只记「最长的连败纪录」（连续前导零的个数）。见过的键越多，总有些桶的纪录越长；把各桶纪录汇总起来，就能反推总共掷了多少次——用极值反推样本量，正是这统计把戏的全部秘密。</span></p>',11)),(l(),n(p,null,{default:e(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%94%AE%20x%22%5D%20--%3E%20H%5B%22%E5%93%88%E5%B8%8C%22%5D%0A%20%20H%20--%3E%20BKT%5B%22%E5%89%8D%20p%20%E6%AF%94%E7%89%B9%E9%80%89%E6%A1%B6%22%5D%0A%20%20H%20--%3E%20RHO%5B%22%E5%85%B6%E4%BD%99%3A%20%E5%89%8D%E5%AF%BC%E9%9B%B6%22%5D%0A%20%20RHO%20--%3E%20MAX%5B%22%E6%A1%B6%E5%86%85%E8%AE%B0%E6%9C%80%E5%A4%A7%20%CF%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,"与布隆：Bloom 成员；HLL 只基数，不能问某个键在不在。空间 \\(O(m)\\) 字节级寄存器（每桶 5–6 比特可打包）。",-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,"分析依赖哈希充分随机。对抗哈希可骗前导零，合同与 CM 一样要随机 \\(h\\)。合并可交换，符合「多机各吃一分片再合并」。",-1)),(l(),n(p,null,{default:e(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%9C%BA%E5%99%A8%20A%20%E7%9A%84%E6%A1%B6%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20M%5B%22%E9%80%90%E6%A1%B6%E5%8F%96%20max%22%5D%0A%20%20B%5B%22%E6%9C%BA%E5%99%A8%20B%20%E7%9A%84%E6%A1%B6%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%20--%3E%20M%0A%20%20M%20--%3E%20E%5B%22%E5%90%88%E5%B9%B6%E5%90%8E%E7%9A%84%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20E%20--%3E%20EST%5B%22%E8%B0%83%E5%92%8C%E5%B9%B3%E5%9D%87%E4%BC%B0%E6%80%BB%E5%9F%BA%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p>过滤器下一课回到成员查询：布谷过滤器比 Bloom 更省且可删。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部偏差校正公式抄完。滑动窗口基数是另一结构。不要把 HLL 当精确 <code>COUNT(DISTINCT)</code> 的法律替代——合同是近似。</p><p>后课默认：基数用 HLL。可删成员用布谷过滤器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HLL：桶内最大前导零，调和平均估基数。</li><li>可合并；空间与误差由桶数定。</li><li>下一课可删除的近似集。</li><li>出处：Flajolet et al., 2007；Durand and Flajolet, 2003。</li></ul>',6))])}const f=d(m,[["render",h]]);export{D as __pageData,f as default};
